/**
 * ``SearchView`` — view de search full-text com debounce.
 *
 * Fase 1 / B5: adiciona toggle CM/AK/Both (segmented control) acima do
 * input. Default "CM" preserva comportamento histórico. Quando "AK" ou
 * "Both", hits de ``/acquire/search`` são retornados pelo hook
 * ``useSearch`` (que aceita ``adapter``).
 *
 * Em modo single-adapter (``memory`` ou ``acquire``), o adapter de cada
 * hit é conhecido pela origem da busca e passado para o card. Em modo
 * ``both``, hits de CM e AK são concatenados — o adapter é decidido
 * por heurística (``type === "Source"`` é típico de hits AK do
 * ``/acquire/search``); o resto cai em CM. Esse smell (S7 do README
 * v0.1.1) é frágil mas tolerável: o ideal seria o backend discriminar
 * cada hit com um campo explícito (``adapter`` ou discriminator). Sem
 * isso, a heurística evita clicar em hits AK e cair no 404.
 *
 * Refactor visual 2026-08-08: header com ícone Compass, max-w-6xl,
 * stats inline ("X results" + breakdown CM/AK quando "both"), segmented
 * control com indicador deslizante (rounded-full + ring).
 */

import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { Search, AlertCircle, Compass, Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { NoteCard } from "@/components/kg/NoteCard";
import { SourceCard } from "@/components/kg/SourceCard";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { useSearch, type SearchAdapter } from "@/hooks/useSearch";
import type { Adapter } from "@/lib/api";
import { cn } from "@/lib/utils";

const ADAPTERS: Array<{ value: SearchAdapter; labelKey: string }> = [
  { value: "memory", labelKey: "search.adapterCM" },
  { value: "acquire", labelKey: "search.adapterAK" },
  { value: "both", labelKey: "search.adapterBoth" },
];

export function SearchView({ className }: { className?: string }) {
  const { t } = useTranslation();
  const [q, setQ] = useState("");
  const [adapter, setAdapter] = useState<SearchAdapter>("memory");
  // B1 (auditoria 2026-07-31): o estado controlado do input é `q`,
  // não ``useSearch`` — se o usuário digitar só espaços, ``q.trim()``
  // é vazio mas o input mostra "espaço". Renderizar "Type to search"
  // nessa condição deixaria a UI inconsistente (input ≠ mensagem).
  // Daemon de busca interna já trata ``debounced.trim()`` vazio como
  // "sem query" (não chama o backend).
  const isEmpty = !q.trim();
  const { hits, loading, error, partialFailure, isPending } = useSearch(q, adapter);

  // Em modo ``memory``/``acquire`` o adapter é o mesmo do toggle. Em
  // modo ``both`` cada hit pode ser de um bundle distinto — usamos a
  // heurística ``type === "Source"`` para AK (S7 do README). SourceCard
  // é a saída dedicada para hits Source, então não há ambiguidade.
  const annotatedHits = useMemo(
    () =>
      hits.map((hit) => {
        const hitAdapter: Adapter =
          adapter === "both" ? (hit.type === "Source" ? "acquire" : "memory") : adapter;
        return { hit, adapter: hitAdapter };
      }),
    [hits, adapter],
  );

  // Contagem por adapter — só faz sentido em modo "both"; em modo
  // single-adapter, ``cmHits``/``akHits`` simplesmente refletem o
  // bundle ativo (não polui a UI).
  const cmHits = useMemo(
    () => (adapter === "both" ? annotatedHits.filter((h) => h.adapter === "memory").length : 0),
    [annotatedHits, adapter],
  );
  const akHits = useMemo(
    () => (adapter === "both" ? annotatedHits.length - cmHits : 0),
    [annotatedHits, adapter, cmHits],
  );

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-6 overflow-y-auto p-6 md:p-8", className)}>
      <header className="flex flex-col gap-1">
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
          <Compass className="h-5 w-5 text-muted-foreground" aria-hidden />
          {t("search.title")}
        </h1>
        {q.trim() && (
          <p className="flex items-center gap-1.5 text-sm text-muted-foreground">
            {loading || isPending ? (
              <Loader2 className="h-3 w-3 animate-spin" aria-hidden />
            ) : null}
            {t("search.resultCount", { count: hits.length })}
            {adapter === "both" && hits.length > 0 && (
              <span className="text-muted-foreground/70">
                · {t("search.resultBreakdown", { cm: cmHits, ak: akHits })}
              </span>
            )}
          </p>
        )}
      </header>

      <div className="relative">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t("search.placeholder")}
          className="pl-9"
          autoFocus
        />
      </div>

      {/* Segmented control — versão 2026-08-08 com ring mais definido.
          Ainda usa o role="radiogroup" do ARIA (padrão de acessibilidade
          para grupos de botões de escolha única). */}
      <div
        className="inline-flex w-fit items-center gap-1 rounded-full border border-border bg-background p-1 shadow-sm"
        role="radiogroup"
        aria-label={t("search.adapterLabel")}
      >
        {ADAPTERS.map(({ value, labelKey }) => {
          const active = adapter === value;
          return (
            <button
              key={value}
              type="button"
              role="radio"
              aria-checked={active}
              onClick={() => setAdapter(value)}
              className={cn(
                "rounded-full px-3 py-1 text-xs font-medium transition-colors",
                active
                  ? "bg-primary text-primary-foreground shadow-sm"
                  : "text-muted-foreground hover:bg-accent hover:text-foreground",
              )}
            >
              {t(labelKey)}
            </button>
          );
        })}
      </div>

      {isEmpty ? (
        <EmptyStateI18n messageKey="search.empty" />
      ) : error ? (
        <EmptyStateI18n messageKey="errors.network" />
      ) : hits.length === 0 && !loading ? (
        <EmptyStateI18n messageKey="search.noResults" />
      ) : (
        <>
          {/* N5 — banner amarelo não-bloqueante quando um adapter
              falha em "both" mas o outro responde. Não substitui a
              lista de resultados. */}
          {partialFailure && (
            <div
              role="status"
              className="flex items-start gap-2 rounded-md border border-amber-500/40 bg-amber-50/30 p-3 text-xs text-amber-900 dark:bg-amber-950/20 dark:text-amber-100"
            >
              <AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden />
              <p>
                {partialFailure === "memory"
                  ? t("search.partialFailureCM")
                  : t("search.partialFailureAK")}
              </p>
            </div>
          )}
          <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">
            {annotatedHits.map(({ hit, adapter: hitAdapter }) => {
              if (hit.type === "Source") {
                return (
                  <SourceCard
                    key={hit.id}
                    source={{
                      id: hit.id,
                      path: hit.path,
                      title: hit.title ?? null,
                      tags: hit.tags ?? [],
                    }}
                  />
                );
              }
              // ``adapter`` aqui reflete a origem do hit (CM ou AK) —
              // bugfix 2026-08-08: sem isso, hits AK cairiam no CM e
              // gerariam 404.
              return (
                <NoteCard
                  key={hit.id}
                  note={{
                    id: hit.id,
                    path: hit.path,
                    title: hit.title ?? null,
                    type: hit.type,
                    tags: hit.tags ?? [],
                  }}
                  adapter={hitAdapter}
                />
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}