/**
 * ``fetchWithTimeout`` — ``fetch`` com AbortController + timeout.
 * Cópia verbatim da WebUI do nanobot (``start_points/nanobot/webui/src/lib/http.ts``).
 *
 * Default 20s para requests de API; ``0`` desabilita o timeout (caller
 * optou por esperar).
 */

export const DEFAULT_HTTP_TIMEOUT_MS = 20_000;

export async function fetchWithTimeout(
  input: RequestInfo | URL,
  init: RequestInit = {},
  timeoutMs: number = DEFAULT_HTTP_TIMEOUT_MS,
): Promise<Response> {
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    return fetch(input, init);
  }

  const controller = typeof AbortController !== "undefined"
    ? new AbortController()
    : null;
  let timeoutId: ReturnType<typeof setTimeout> | undefined;

  // O ``signal`` do caller era DESCARTADO sempre que havia timeout ativo
  // (o default), porque o controller interno o sobrescrevia. Quem passasse
  // ``{ signal }`` para cancelar (troca de rota, unmount, apiBase nova)
  // não cancelava nada e o request virava zumbi até o timeout de 20s.
  // Compomos os dois: quem abortar primeiro, aborta o fetch.
  const external = init.signal;
  const onExternalAbort = () => controller?.abort(external?.reason);
  if (external && controller) {
    if (external.aborted) controller.abort(external.reason);
    else external.addEventListener("abort", onExternalAbort, { once: true });
  }

  const request = fetch(input, {
    ...init,
    signal: controller?.signal ?? external,
  });
  const timeout = new Promise<Response>((_, reject) => {
    timeoutId = setTimeout(() => {
      reject(new Error(`Request timed out after ${timeoutMs}ms`));
      controller?.abort();
    }, timeoutMs);
  });

  try {
    return await Promise.race([request, timeout]);
  } finally {
    if (timeoutId !== undefined) clearTimeout(timeoutId);
    external?.removeEventListener("abort", onExternalAbort);
  }
}
