/**
 * Resolve a URL base do adapter HTTP. Por padrão, o P10 serve o adapter
 * no mesmo origin da SPA, em ``/kg-interface/api``. Em dev, pode-se
 * sobrescrever via ``VITE_API_BASE`` (env var injetada em build time).
 */

const DEFAULT_BASE = "/kg-interface/api";

export function resolveApiBase(): string {
  // Vite injeta ``import.meta.env.VITE_API_BASE`` em build time se setada.
  // Em produção, devolve o default (mesmo origin).
  const fromEnv = import.meta.env.VITE_API_BASE;
  if (typeof fromEnv === "string" && fromEnv.trim().length > 0) {
    return fromEnv.replace(/\/+$/, "");
  }
  return DEFAULT_BASE;
}
