/**
 * ``ReviewCard`` — uma entrada da fila de revisão (P11).
 *
 * O agente de manutenção marca sinais que não dispara sozinho; este card é
 * onde o humano resolve. As ações oferecidas vêm de ``related_actions`` da
 * própria entrada — a UI não decide o que faz sentido para cada ``kind``,
 * quem decide é quem levantou o sinal.
 *
 * Entradas resolvidas/reconhecidas continuam renderizando (histórico), mas
 * com a única ação disponível sendo ``reopen``. Esconder o histórico
 * tiraria do humano a informação de que aquele sinal já foi visto antes.
 */

import { useTranslation } from "react-i18next";
import { AlertTriangle, RotateCcw, Shield, Snowflake, Archive, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/kg/Badge";
import { formatTimestamp } from "@/lib/format";
import type { ReviewEntry, ReviewResolution } from "@/lib/types";
import { cn } from "@/lib/utils";

/**
 * Cor por confiança. `high` é vermelho não por ser "erro", mas porque é o
 * sinal em que o agente age sozinho — o humano precisa ver primeiro.
 */
const CONFIDENCE_STYLES: Record<string, string> = {
  high: "border-destructive/50 bg-destructive/5",
  medium: "border-amber-500/50 bg-amber-500/5",
  low: "border-border bg-muted/30",
};

/**
 * Ações sugeridas → resolution correspondente + ícone.
 *
 * `keep_as_is` e `set_protected_true` mapeiam para resoluções distintas de
 * propósito: a primeira só fecha o sinal, a segunda também protege a nota
 * contra a próxima rodada automática.
 */
const ACTION_MAP: Record<
  string,
  { resolution: ReviewResolution; icon: typeof Check; variant?: "destructive" | "outline" }
> = {
  keep_as_is: { resolution: "resolve_keep", icon: Check, variant: "outline" },
  move_to_cold: { resolution: "resolve_cold", icon: Snowflake },
  forget: { resolution: "resolve_forget", icon: Archive, variant: "destructive" },
  move_to_archive: { resolution: "resolve_forget", icon: Archive, variant: "destructive" },
};

export function ReviewCard({
  entry,
  onResolve,
  onProtect,
  busy = false,
  className,
}: {
  entry: ReviewEntry;
  onResolve: (resolution: ReviewResolution) => void;
  /** ``set_protected_true`` não é uma resolution — é a outra tool. */
  onProtect?: () => void;
  busy?: boolean;
  className?: string;
}) {
  const { t } = useTranslation();
  const isPending = entry.status === "pending";

  // ``kind`` vem do backend como string livre (ver ReviewEntrySchema): se
  // for um kind novo que a UI ainda não traduz, mostramos o valor cru em
  // vez de uma chave i18n faltando.
  const kindLabel = t(`notes.review.kind.${entry.kind}`, { defaultValue: entry.kind });

  return (
    <div
      className={cn(
        "rounded-md border p-3",
        isPending ? CONFIDENCE_STYLES[entry.confidence] ?? CONFIDENCE_STYLES.low : "border-border bg-muted/20 opacity-75",
        className,
      )}
      data-testid={`review-${entry.kind}`}
    >
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2">
          <AlertTriangle className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
          <span className="text-xs font-medium uppercase tracking-wide">{kindLabel}</span>
        </div>
        <div className="flex shrink-0 items-center gap-1">
          <Badge variant={isPending ? "default" : "secondary"}>
            {t(`notes.review.confidence.${entry.confidence}`, {
              defaultValue: entry.confidence,
            })}
          </Badge>
          {!isPending && (
            <Badge variant="outline">
              {t(`notes.review.status.${entry.status}`, { defaultValue: entry.status })}
            </Badge>
          )}
        </div>
      </div>

      <p className="mt-2 text-sm">{entry.reason}</p>

      <div className="mt-1 text-xs text-muted-foreground">
        {t("notes.review.flaggedBy", {
          when: formatTimestamp(entry.flagged_at),
          who: entry.flagged_by,
        })}
        {entry.reopened_at ? (
          <> · {t("notes.review.reopenedAt", { when: formatTimestamp(entry.reopened_at) })}</>
        ) : null}
      </div>

      <div className="mt-3 flex flex-wrap gap-2">
        {isPending ? (
          <>
            <Button
              size="sm"
              variant="outline"
              disabled={busy}
              onClick={() => onResolve("acknowledge")}
            >
              {t("notes.review.action.acknowledge")}
            </Button>
            {entry.related_actions.includes("set_protected_true") && onProtect ? (
              <Button size="sm" variant="outline" disabled={busy} onClick={onProtect}>
                <Shield className="mr-1 h-3 w-3" aria-hidden />
                {t("notes.review.action.set_protected_true")}
              </Button>
            ) : null}
            {entry.related_actions.map((action) => {
              const mapped = ACTION_MAP[action];
              if (!mapped) return null;
              const Icon = mapped.icon;
              return (
                <Button
                  key={action}
                  size="sm"
                  variant={mapped.variant}
                  disabled={busy}
                  onClick={() => onResolve(mapped.resolution)}
                >
                  <Icon className="mr-1 h-3 w-3" aria-hidden />
                  {t(`notes.review.action.${action}`, { defaultValue: action })}
                </Button>
              );
            })}
          </>
        ) : (
          <Button size="sm" variant="outline" disabled={busy} onClick={() => onResolve("reopen")}>
            <RotateCcw className="mr-1 h-3 w-3" aria-hidden />
            {t("notes.review.action.reopen")}
          </Button>
        )}
      </div>
    </div>
  );
}
