/**
 * ``ConflictResolver`` — diff 3-vias para resolver 409 do CAS (Fase 2 / B3).
 *
 * Quando ``PUT /notes/:id/body`` retorna 409 com body estruturado
 * (``{status: "conflict", base_body_hash, current_body_hash, server_body}``),
 * a UI mostra 3 painéis lado-a-lado:
 * - **Local** (versão editada pelo humano) — referência primária.
 * - **Servidor** (versão atual no backend) — atualizada por terceiro.
 * - **Base** — fallback para diff, mostrando o ``base_body_hash`` que a
 *   UI tinha originalmente.
 *
 * Botões:
 * - **Cancel** — fecha, descarta local (sem salvar).
 * - **Reload** — fecha, recarrega servidor (perde edição local).
 * - **Merge** — abre mini-editor onde humano escolhe linha-a-linha.
 * - **Overwrite** — força PUT sem ``base_body_hash`` (DC-S1: bloqueado por
 *   default; requer ``localStorage["settings.advanced.allowOverwrite"] ===
 *   "true"``).
 */

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { ApiError } from "@/lib/api";
import { AlertTriangle, Skull } from "lucide-react";
import { cn } from "@/lib/utils";

export interface BodyConflict {
  status: "conflict";
  base_body_hash: string;
  current_body_hash: string;
  server_body: string;
}

function isOverwriteAllowed(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return window.localStorage.getItem("settings.advanced.allowOverwrite") === "true";
  } catch {
    return false;
  }
}

export function ConflictResolver({
  conflict,
  localBody,
  open,
  onResolve,
  onCancel,
  onReload,
}: {
  conflict: BodyConflict;
  localBody: string;
  open: boolean;
  /**
   * Chamado quando humano escolhe merge ou overwrite — body final a
   * salvar. Retorna ``Promise<void>`` que o ConflictResolver aguarda
   * antes de fechar o dialog. Se a promise **rejeitar**, o dialog
   * permanece aberto (erro fica visível no note) e o humano pode
   * tentar de novo ou cancelar.
   *
   * Bug fix B4 (auditoria 2026-07-31): antes deste contrato o
   * ``onResolve`` era fire-and-forget — o dialog fechava antes da
   * promise resolver, então se o save falhasse o humano perdia o
   * conteúdo do merge.
   */
  onResolve: (merged: string) => Promise<void>;
  onCancel: () => void;
  onReload: () => void | Promise<void>;
}) {
  const { t } = useTranslation();
  const [merging, setMerging] = useState(false);
  const [merged, setMerged] = useState(localBody);
  const [resolving, setResolving] = useState(false);
  const [resolveError, setResolveError] = useState<string | null>(null);
  // N4 (auditoria #2, 2026-07-31): substitui ``window.confirm`` por
  // um AlertDialog interno (i18n + estilo consistente + não-bloqueante
  // para a thread). ``overwriteConfirming`` alterna o segundo dialog
  // antes de chamar ``onResolve``.
  const [overwriteConfirming, setOverwriteConfirming] = useState(false);
  const overwriteAllowed = isOverwriteAllowed();

  async function performResolve(body: string) {
    setResolveError(null);
    setResolving(true);
    try {
      await onResolve(body);
    } catch (e) {
      if (e instanceof ApiError && e.status === 409) {
        setResolveError(null);
      } else {
        setResolveError(e instanceof Error ? e.message : String(e));
      }
    } finally {
      setResolving(false);
    }
  }

  return (
    <>
    <AlertDialog open={open} onOpenChange={(o) => !o && onCancel()}>
      <AlertDialogContent className="max-w-4xl">
        <AlertDialogHeader>
          <AlertDialogTitle className="flex items-center gap-2">
            <AlertTriangle className="h-4 w-4 text-amber-500" />
            {t("notes.editor.casConflict.title")}
          </AlertDialogTitle>
          <AlertDialogDescription>
            {t("notes.editor.casConflict.body")}
          </AlertDialogDescription>
        </AlertDialogHeader>

        {!merging ? (
          <div className="grid grid-cols-2 gap-3">
            <Pane
              title={t("notes.editor.casConflict.paneLocal")}
              body={localBody}
              tone="warning"
            />
            <Pane
              title={t("notes.editor.casConflict.paneServer")}
              body={conflict.server_body}
              tone="muted"
            />
          </div>
        ) : (
          <div className="flex flex-col gap-2">
            <p className="text-xs text-muted-foreground">
              {t("notes.editor.casConflict.mergeHint")}
            </p>
            <Textarea
              className="min-h-[200px] font-mono text-sm"
              value={merged}
              onChange={(e) => setMerged(e.target.value)}
              disabled={resolving}
            />
          </div>
        )}

        {resolveError && (
          <p
            className="rounded-md border border-destructive/40 bg-destructive/10 p-2 text-xs text-destructive"
            role="alert"
          >
            {resolveError}
          </p>
        )}

        <AlertDialogFooter>
          <Button variant="outline" onClick={onCancel} disabled={resolving}>
            {t("notes.editor.casConflict.cancel")}
          </Button>
          <Button variant="outline" onClick={onReload} disabled={resolving}>
            {t("notes.editor.casConflict.reload")}
          </Button>
          {!merging ? (
            <Button onClick={() => setMerging(true)} disabled={resolving}>
              {t("notes.editor.casConflict.merge")}
            </Button>
          ) : (
            <Button
              disabled={resolving}
              onClick={() => void performResolve(merged)}
            >
              {t("notes.editor.casConflict.mergeSave")}
            </Button>
          )}
          {overwriteAllowed && !merging && (
            <Button
              variant="destructive"
              disabled={resolving}
              // N4: abre AlertDialog interno em vez de ``window.confirm``.
              onClick={() => setOverwriteConfirming(true)}
            >
              {t("notes.editor.casConflict.overwrite")}
            </Button>
          )}
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>

    {/* N4 — second dialog: confirmação destrutiva para overwrite. */}
    <AlertDialog open={overwriteConfirming} onOpenChange={setOverwriteConfirming}>
      <AlertDialogContent className="max-w-md">
        <AlertDialogHeader>
          <AlertDialogTitle className="flex items-center gap-2">
            <Skull className="h-4 w-4 text-destructive" />
            {t("notes.editor.casConflict.overwriteTitle")}
          </AlertDialogTitle>
          <AlertDialogDescription>
            {t("notes.editor.casConflict.overwriteConfirm")}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <Button
            variant="outline"
            onClick={() => setOverwriteConfirming(false)}
            disabled={resolving}
          >
            {t("notes.actions.cancel")}
          </Button>
          <Button
            variant="destructive"
            disabled={resolving}
            onClick={async () => {
              setOverwriteConfirming(false);
              await performResolve(localBody);
            }}
          >
            {t("notes.editor.casConflict.overwrite")}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
    </>
  );
}

function Pane({
  title,
  body,
  tone,
}: {
  title: string;
  body: string;
  tone: "warning" | "muted";
}) {
  return (
    <div
      className={cn(
        "flex flex-col gap-1 rounded-md border p-2",
        tone === "warning"
          ? "border-amber-500/50 bg-amber-50/30 dark:bg-amber-950/20"
          : "border-border bg-muted/30",
      )}
    >
      <p className="text-xs font-medium text-muted-foreground">{title}</p>
      <pre className="max-h-[200px] overflow-auto whitespace-pre-wrap break-words font-mono text-xs">
        {body}
      </pre>
    </div>
  );
}