/**
 * Helpers de formatação. Pattern idêntico ao ``format.ts`` da WebUI
 * (deriveTitle).
 */

const MAX_TITLE_LEN = 80;

/** Deriva um título curto: usa ``title`` se presente, senão a 1ª linha
 *  não-vazia do ``body``, truncada. */
export function deriveTitle(input: string | null | undefined, fallback: string): string {
  if (!input) return fallback;
  const trimmed = input.trim();
  if (!trimmed) return fallback;
  // Pega a primeira linha que não é só markdown cru (não heading, não frontmatter)
  for (const line of trimmed.split(/\r?\n/)) {
    const cleaned = line.replace(/^#+\s*/, "").trim();
    if (!cleaned) continue;
    if (cleaned.length <= MAX_TITLE_LEN) return cleaned;
    return `${cleaned.slice(0, MAX_TITLE_LEN - 1)}…`;
  }
  return fallback;
}

/** Formata SHA-256 para exibição curta (primeiros 8 chars). */
export function shortHash(hash: string | null | undefined, fallback = "—"): string {
  if (!hash) return fallback;
  return hash.slice(0, 8);
}

/** Formata data ISO para ``YYYY-MM-DD HH:MM``. */
export function formatTimestamp(iso: string | null | undefined): string {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

/** Formata timestamp ISO em tempo relativo ("5 min ago", "3 hours ago").
 *  Usado pela ``GraphView`` (last_build), StatsView e futuros placeholders.
 *  Implementação leve sem dependência de date-fns. */
export function formatRelativeTime(iso: string | null | undefined): string {
  if (!iso) return "—";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  const diffMs = Date.now() - d.getTime();
  const diffSec = Math.round(diffMs / 1000);
  if (diffSec < 0) {
    // Relógio do cliente à frente do servidor — usar "in N min" para
    // sinalizar honestamente em vez de mostrar "0 sec ago".
    return formatAbsoluteFuture(Math.abs(diffSec));
  }
  if (diffSec < 60) return `${diffSec}s ago`;
  const diffMin = Math.round(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m ago`;
  const diffHour = Math.round(diffMin / 60);
  if (diffHour < 24) return `${diffHour}h ago`;
  const diffDay = Math.round(diffHour / 24);
  if (diffDay < 30) return `${diffDay}d ago`;
  const diffMonth = Math.round(diffDay / 30);
  if (diffMonth < 12) return `${diffMonth}mo ago`;
  return `${Math.round(diffMonth / 12)}y ago`;
}

/** Helper interno — formata segundos em "in Nh/Nm" para o caso de clock skew. */
function formatAbsoluteFuture(absSec: number): string {
  if (absSec < 60) return `in ${absSec}s`;
  const absMin = Math.round(absSec / 60);
  if (absMin < 60) return `in ${absMin}m`;
  const absHour = Math.round(absMin / 60);
  if (absHour < 24) return `in ${absHour}h`;
  return `in ${Math.round(absHour / 24)}d`;
}
