/**
 * Native KG transport for the SPA. The gateway, not this client,
 * authorizes and executes mutations. Credentials stay in memory only.
 */

type Bootstrap = {
  api_token?: string;
  token?: string;
  ws_url: string;
  expires_in?: number;
  limits?: { transport?: { max_frame_bytes?: number } };
};

type Pending = {
  resolve: (value: unknown) => void;
  reject: (error: Error) => void;
  timer: ReturnType<typeof setTimeout>;
};

export class GatewayTransportError extends Error {
  constructor(public readonly status: number, message: string) {
    super(message);
    this.name = "GatewayTransportError";
  }
}

export class GatewayKgTransport {
  private bootstrapPromise: Promise<Bootstrap> | null = null;
  private bootstrapExpiresAt = 0;
  private socket: WebSocket | null = null;
  private connectingSocket: WebSocket | null = null;
  private socketPromise: Promise<WebSocket> | null = null;
  private readonly pending = new Map<string, Pending>();
  private closed = false;

  /** Supplied by a credential prompt or trusted host, never persisted or sent in a URL. */
  constructor(private readonly bootstrapSecret: string | null = null) {}

  /** Check the gateway before mounting KG views; credentials remain in memory. */
  async ready(): Promise<void> {
    await this.bootstrap();
  }

  private async bootstrap(force = false): Promise<Bootstrap> {
    if (this.closed) throw new GatewayTransportError(0, "Gateway transport closed");
    if (force) this.bootstrapPromise = null;
    if (this.bootstrapPromise && Date.now() < this.bootstrapExpiresAt - 10_000) {
      return this.bootstrapPromise;
    }
    this.bootstrapPromise = (async () => {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 10_000);
      let response: Response;
      try {
        response = await fetch("/webui/bootstrap", {
          credentials: "same-origin", signal: controller.signal,
          headers: {
            Accept: "application/json",
            ...(this.bootstrapSecret ? { "X-Nanobot-Auth": this.bootstrapSecret } : {}),
          },
        });
      } catch (error) {
        if (controller.signal.aborted) throw new GatewayTransportError(504, "Gateway bootstrap timed out");
        throw error;
      } finally {
        clearTimeout(timeout);
      }
      if (!response.ok) throw new GatewayTransportError(response.status, "Gateway bootstrap unavailable");
      const data: unknown = await response.json();
      if (!isBootstrap(data)) throw new GatewayTransportError(502, "Gateway bootstrap contract is invalid");
      this.bootstrapExpiresAt = Date.now() + (data.expires_in ?? 60) * 1000;
      return data;
    })();
    try {
      return await this.bootstrapPromise;
    } catch (error) {
      this.bootstrapPromise = null;
      throw error;
    }
  }

  /** GET routes never put credentials into URLs or persistent browser storage. */
  async get(path: string, signal?: AbortSignal): Promise<Response> {
    if (!path.startsWith("/kg-interface/api/") || path.includes("#")) {
      throw new GatewayTransportError(400, "Invalid KG API path");
    }
    if (new URL(path, window.location.origin).searchParams.has("token")) {
      throw new GatewayTransportError(400, "KG credentials must not appear in URLs");
    }
    for (let attempt = 0; attempt < 2; attempt++) {
      const credentials = await this.bootstrap(attempt === 1);
      const response = await fetch(path, {
        method: "GET", signal, credentials: "same-origin",
        headers: {
          ...(credentials.api_token ? { Authorization: `Bearer ${credentials.api_token}` } : {}),
          Accept: "application/json",
        },
      });
      if (response.status !== 401 || attempt === 1) return response;
    }
    throw new GatewayTransportError(401, "Gateway authentication expired");
  }

  /** Send one allowlisted action over an authenticated WebUI socket. */
  async mutate<T>(action: string, payload: Record<string, unknown>, timeoutMs = 20_000): Promise<T> {
    if (!/^[a-z][a-z0-9_.]{0,127}$/.test(action)) {
      throw new GatewayTransportError(400, "Invalid action");
    }
    const { socket, maxFrameBytes } = await this.connect();
    const requestId = crypto.randomUUID();
    const frame = JSON.stringify({ type: "webui_request", request_id: requestId, action, payload });
    if (new TextEncoder().encode(frame).byteLength > maxFrameBytes) {
      throw new GatewayTransportError(413, "Gateway mutation exceeds the WebSocket frame limit");
    }
    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(requestId);
        reject(new GatewayTransportError(504, "Gateway mutation timed out; check state before retrying"));
      }, timeoutMs);
      this.pending.set(requestId, { resolve: (value) => resolve(value as T), reject, timer });
      try {
        socket.send(frame);
      } catch (error) {
        clearTimeout(timer);
        this.pending.delete(requestId);
        reject(error);
      }
    });
  }

  private maxFrameBytes = 64 * 1024;

  private async connect(): Promise<{ socket: WebSocket; maxFrameBytes: number }> {
    if (this.socket?.readyState === WebSocket.OPEN) return { socket: this.socket, maxFrameBytes: this.maxFrameBytes };
    if (this.socketPromise) return { socket: await this.socketPromise, maxFrameBytes: this.maxFrameBytes };
    // A WS credential is single-use, so a new connection always bootstraps.
    this.socketPromise = (async () => {
      const credentials = await this.bootstrap(true);
      if (this.closed) throw new GatewayTransportError(0, "Gateway transport closed");
      const offeredLimit = credentials.limits?.transport?.max_frame_bytes;
      this.maxFrameBytes = typeof offeredLimit === "number" && Number.isSafeInteger(offeredLimit)
        && offeredLimit >= 1024 ? offeredLimit : 64 * 1024;
      const url = new URL(credentials.ws_url);
      if (!["ws:", "wss:"].includes(url.protocol) || url.username || url.password || url.search || url.hash) {
        throw new GatewayTransportError(502, "Invalid gateway WebSocket URL");
      }
       const loopbackDev = import.meta.env.DEV
         && ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)
         && ["localhost", "127.0.0.1", "[::1]"].includes(window.location.hostname);
       if ((!loopbackDev && url.hostname !== window.location.hostname) || (
        !import.meta.env.DEV && url.host !== window.location.host
      )) {
        throw new GatewayTransportError(502, "Gateway WebSocket host differs from the browser host");
      }
       if (credentials.token) url.searchParams.set("token", credentials.token);
      url.searchParams.set("client_id", `kg-${crypto.randomUUID()}`);
      const socket = new WebSocket(url.toString());
      this.connectingSocket = socket;
      return await new Promise<WebSocket>((resolve, reject) => {
        let opened = false;
        const handshakeTimer = setTimeout(() => {
          reject(new GatewayTransportError(504, "Gateway WebSocket handshake timed out"));
          socket.close();
        }, 10_000);
        socket.onopen = () => {
          if (this.closed) { socket.close(); return; }
          clearTimeout(handshakeTimer);
          opened = true;
          this.connectingSocket = null;
          this.socket = socket;
          resolve(socket);
        };
        socket.onerror = () => {
          clearTimeout(handshakeTimer);
          reject(new GatewayTransportError(503, "Gateway WebSocket connection failed"));
          socket.close();
        };
        socket.onmessage = (event) => this.receive(event.data);
        socket.onclose = () => {
          clearTimeout(handshakeTimer);
          if (this.connectingSocket === socket) this.connectingSocket = null;
          if (!opened) reject(new GatewayTransportError(503, "Gateway WebSocket handshake rejected"));
          if (this.socket === socket) this.socket = null;
          for (const request of this.pending.values()) {
            clearTimeout(request.timer);
            request.reject(new GatewayTransportError(503, "Gateway disconnected; check state before retrying"));
          }
          this.pending.clear();
        };
      });
    })();
    try {
      return { socket: await this.socketPromise, maxFrameBytes: this.maxFrameBytes };
    } finally {
      this.socketPromise = null;
    }
  }

  private receive(raw: unknown): void {
    if (typeof raw !== "string") return;
    let event: unknown;
    try { event = JSON.parse(raw); } catch { return; }
    if (!isResponse(event)) return;
    const request = this.pending.get(event.request_id);
    if (!request) return;
    this.pending.delete(event.request_id);
    clearTimeout(request.timer);
    if (event.ok) request.resolve(event.result);
    else request.reject(new GatewayTransportError(event.error.status, event.error.message));
  }

  close(): void {
    this.closed = true;
    this.bootstrapPromise = null;
    this.connectingSocket?.close();
    this.connectingSocket = null;
    this.socket?.close();
    this.socket = null;
    for (const request of this.pending.values()) {
      clearTimeout(request.timer);
      request.reject(new GatewayTransportError(0, "Gateway transport closed"));
    }
    this.pending.clear();
  }
}

function isBootstrap(value: unknown): value is Bootstrap {
  if (!value || typeof value !== "object") return false;
  const data = value as Record<string, unknown>;
  const tokenBootstrap = typeof data.api_token === "string" && !!data.api_token
    && typeof data.token === "string" && !!data.token;
  const trustedProxyBootstrap = data.api_token === undefined && data.token === undefined;
  const validExpiry = data.expires_in === undefined
    ? trustedProxyBootstrap
    : typeof data.expires_in === "number" && Number.isFinite(data.expires_in) && data.expires_in > 0;
  return (tokenBootstrap || trustedProxyBootstrap)
    && typeof data.ws_url === "string" && validExpiry;
}

function isResponse(value: unknown): value is {
  request_id: string; ok: boolean; result: unknown; error: { status: number; message: string };
} {
  if (!value || typeof value !== "object") return false;
  const event = value as Record<string, unknown>;
  if (event.event !== "webui_response" || typeof event.request_id !== "string" || typeof event.ok !== "boolean") return false;
  if (event.ok) return true;
  const error = event.error;
  return !!error && typeof error === "object"
    && typeof (error as Record<string, unknown>).status === "number"
    && typeof (error as Record<string, unknown>).message === "string";
}
