import { useEffect, useMemo, useState } from "react";
import { forceCenter, forceLink, forceManyBody, forceSimulation, type SimulationNodeDatum } from "d3-force";
import type { GraphData } from "@/lib/types";

const WIDTH = 900;
const HEIGHT = 520;
export const MAX_RENDER_NODES = 240;
export const MAX_RENDER_LINKS = 600;

interface Node extends SimulationNodeDatum {
  id: string;
  label: string;
  type?: string;
}

interface Link {
  source: string | Node;
  target: string | Node;
}

/** Keep the simulation bounded even when the 8 MiB graph endpoint contains thousands of nodes. */
export function graphSample(data: GraphData): { nodes: Node[]; links: Link[] } {
  const nodes = data.nodes.slice(0, MAX_RENDER_NODES).map((node, index) => ({
    id: node.id,
    label: node.label ?? node.id,
    type: typeof node.type === "string" ? node.type : undefined,
    x: WIDTH / 2 + Math.cos(index * 2.39996) * Math.sqrt(index) * 18,
    y: HEIGHT / 2 + Math.sin(index * 2.39996) * Math.sqrt(index) * 13,
  }));
  const ids = new Set(nodes.map((node) => node.id));
  const links = data.links.filter((link) => ids.has(link.source) && ids.has(link.target))
    .slice(0, MAX_RENDER_LINKS).map((link) => ({ source: link.source, target: link.target }));
  return { nodes, links };
}

export function GraphCanvas({ data, onSelect }: {
  data: GraphData;
  onSelect: (node: { id: string; type?: string }) => void;
}) {
  const sample = useMemo(() => graphSample(data), [data]);
  const [frame, setFrame] = useState(0);

  useEffect(() => {
    const simulation = forceSimulation<Node>(sample.nodes)
      .force("charge", forceManyBody<Node>().strength(-100))
      .force("links", forceLink<Node, Link>(sample.links).id((node) => node.id).distance(60))
      .force("center", forceCenter(WIDTH / 2, HEIGHT / 2));
    let ticks = 0;
    simulation.on("tick", () => {
      if (++ticks % 4 === 0) setFrame(ticks);
    });
    simulation.on("end", () => setFrame(ticks));
    return () => { simulation.stop(); };
  }, [sample]);

  // frame triggers a React redraw of the positions mutated by d3-force.
  void frame;
  return <svg viewBox={`0 0 ${WIDTH} ${HEIGHT}`} role="img" aria-label="Knowledge graph"
    className="h-full w-full" data-testid="graph-canvas">
    {sample.links.map((link, index) => {
      const source = link.source as Node;
      const target = link.target as Node;
      return <line key={index} x1={source.x} y1={source.y} x2={target.x} y2={target.y}
        stroke="currentColor" className="text-muted-foreground/40" />;
    })}
    {sample.nodes.map((node) => <g key={node.id} transform={`translate(${node.x ?? 0}, ${node.y ?? 0})`}
      role="link" tabIndex={0} aria-label={node.label}
      className="cursor-pointer text-primary focus:outline-none"
      onClick={() => onSelect(node)}
      onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") {
        event.preventDefault(); onSelect(node);
      } }}>
      <circle r={7} fill="currentColor" />
      <title>{node.label}</title>
    </g>)}
  </svg>;
}
