/**
 * ``NoteView`` — visualização read-only de uma nota + ações (edit, archive).
 *
 * O archive pede confirmação explícita (AlertDialog) antes de mover a
 * nota para ``_archive/`` — não é uma operação destrutiva mas é
 * irreversível pelo front (precisa de git revert manual).
 */

import { useEffect, useRef, useState, type MouseEvent } from "react";
import { useTranslation } from "react-i18next";
import { Pencil, Archive, ArrowLeft, Download, Shield, Snowflake } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/kg/Badge";
import { NotePreview } from "@/components/kg/NotePreview";
import { ReviewCard } from "@/components/kg/ReviewCard";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import {
  ApiError,
  noteHistory,
  resolveReview,
  setLifecycle,
  setProtected,
} from "@/lib/api";
import { useNote } from "@/hooks/useNote";
import { useHashRoute } from "@/hooks/useHashRoute";
import { useKgClient } from "@/providers/KgClientProvider";
import { Link } from "@/lib/Link";
import { formatTimestamp, shortHash } from "@/lib/format";
import { downloadNoteAsMarkdown } from "@/lib/download";
import type { CommitEntry, ReviewResolution } from "@/lib/types";
import { cn } from "@/lib/utils";

export function NoteView({ noteId, className }: { noteId: string; className?: string }) {
  const { t } = useTranslation();
  const { apiBase } = useKgClient();
  const [, navigate] = useHashRoute();
  const { note, loading, error, archive, refresh } = useNote(noteId);
  // P11: uma única flag de "escrevendo" para protected/lifecycle/review.
  // Elas competem pelo mesmo CAS da nota — deixar dois botões ativos em
  // paralelo produziria um 409 previsível em vez de uma UI honesta.
  const [p11Busy, setP11Busy] = useState(false);
  const [p11Error, setP11Error] = useState<string | null>(null);
  const [archiveOpen, setArchiveOpen] = useState(false);
  const [archiveError, setArchiveError] = useState<string | null>(null);
  const [archiveBusy, setArchiveBusy] = useState(false);
  // Histórico git real (commits que tocaram o path da nota). O endpoint
  // ``/notes/:id/history`` já existia no adapter (gitstore.log_for) e o
  // client ``noteHistory`` já era exportado + tipado, mas nunca era
  // chamado aqui — a seção "History" só mostrava os hashes de CAS,
  // nunca o log git de fato. Contador de geração: mesmo padrão dos
  // demais fetches desta view (evita resposta antiga sobrescrever ao
  // navegar rápido entre notas).
  const [history, setHistory] = useState<CommitEntry[] | null>(null);
  const historyRequestIdRef = useRef(0);

  /**
   * Envolve as mutações da P11: serializa, traduz erro e recarrega a nota.
   *
   * O ``refresh`` no fim não é cosmético — ``resolve_cold`` e
   * ``resolve_forget`` mudam o frontmatter (e, no forget, o próprio path),
   * então o estado local fica obsoleto na hora.
   */
  async function runP11(action: () => Promise<unknown>): Promise<void> {
    setP11Busy(true);
    setP11Error(null);
    try {
      await action();
      await refresh();
    } catch (err) {
      // 409 = alguém editou a nota desde o carregamento. Recarregar é a
      // ação certa, não repetir a mesma request.
      const conflict = err instanceof ApiError && err.status === 409;
      setP11Error(conflict ? t("notes.p11.conflict") : t("errors.network"));
      if (conflict) await refresh();
    } finally {
      setP11Busy(false);
    }
  }

  useEffect(() => {
    const requestId = ++historyRequestIdRef.current;
    setHistory(null);
    void noteHistory(apiBase, noteId)
      .then((d) => {
        if (historyRequestIdRef.current !== requestId) return;
        setHistory(d.history);
      })
      .catch(() => {
        if (historyRequestIdRef.current !== requestId) return;
        setHistory([]);
      });
  }, [apiBase, noteId]);

  const confirmArchive = async (event: MouseEvent<HTMLButtonElement>) => {
    // ``AlertDialogAction`` do Radix é implementado como ``Dialog.Close``
    // por baixo — clicar nele fecha o dialog IMEDIATAMENTE, antes do
    // ``onClick`` assíncrono resolver, o que descartava o busy state e o
    // erro (o dialog já tinha sumido quando ``archiveError`` era setado).
    // ``preventDefault`` no evento composto impede o auto-close; fechamos
    // manualmente só no caminho de sucesso, abaixo.
    event.preventDefault();
    setArchiveBusy(true);
    setArchiveError(null);
    try {
      await archive("archive via UI");
      setArchiveOpen(false);
      navigate({ kind: "notes" });
    } catch (e) {
      setArchiveError(
        e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message,
      );
    } finally {
      setArchiveBusy(false);
    }
  };

  if (loading) return <SurfaceLoadingFallback className={className} />;
  if (error) return <EmptyStateI18n messageKey="errors.network" className={className} />;
  if (!note) return <EmptyStateI18n messageKey="errors.notFound" className={className} />;

  return (
    <div className={cn("flex h-full flex-col gap-4 overflow-y-auto p-6", className)}>
      <div className="flex items-center justify-between">
        <Link
          to={{ kind: "notes" }}
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft className="h-3.5 w-3.5" />
          {t("notes.actions.back")}
        </Link>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            // Bugfix 2026-08-08: download do body como .md. O conteúdo
            // já está em memória (readNote populou ``note.body``) e
            // o ``note.path`` dá o filename natural. Sem confirmação
            // — operação não-destrutiva, é só um save local.
            onClick={() => note && downloadNoteAsMarkdown(note.path, note.body)}
            disabled={!note}
          >
            <Download className="mr-1 h-3.5 w-3.5" />
            {t("notes.actions.download")}
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => navigate({ kind: "note-edit", id: noteId })}
          >
            <Pencil className="mr-1 h-3.5 w-3.5" />
            {t("notes.actions.edit")}
          </Button>
          <Button variant="ghost" size="sm" onClick={() => setArchiveOpen(true)}>
            <Archive className="mr-1 h-3.5 w-3.5" />
            {t("notes.actions.archive")}
          </Button>
        </div>
      </div>

      <header>
        <h1 className="text-2xl font-semibold">
          {note.frontmatter.title ?? note.id}
        </h1>
        <div className="mt-2 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          {note.frontmatter.type && <Badge variant="outline">{note.frontmatter.type}</Badge>}
          <span className="font-mono">{note.id}</span>
          {note.frontmatter.protected ? (
            <Badge variant="default" title={t("notes.protected.description")}>
              <Shield className="mr-1 h-3 w-3" aria-hidden />
              {t("notes.protected.label")}
            </Badge>
          ) : null}
          {note.frontmatter.lifecycle === "cold" ? (
            <Badge variant="outline" title={t("notes.lifecycle.coldDescription")}>
              <Snowflake className="mr-1 h-3 w-3" aria-hidden />
              {t("notes.lifecycle.cold")}
            </Badge>
          ) : null}
          {note.frontmatter.tags && note.frontmatter.tags.length > 0
            ? note.frontmatter.tags.map((tag) => (
                <Badge key={tag} variant="secondary">
                  {tag}
                </Badge>
              ))
            : null}
        </div>

        {/* P11: controles de policy. Ficam no header, junto dos badges que
            eles alteram, e não numa aba separada — a decisão de proteger
            uma nota é tomada olhando para ela. */}
        <div className="mt-3 flex flex-wrap items-center gap-2 rounded-md border border-border p-2">
          <Button
            size="sm"
            variant={note.frontmatter.protected ? "default" : "outline"}
            disabled={p11Busy}
            onClick={() =>
              void runP11(() =>
                setProtected(apiBase, note.id, !note.frontmatter.protected, {
                  expectedContentHash: note.content_hash,
                }),
              )
            }
          >
            <Shield className="mr-1 h-3.5 w-3.5" aria-hidden />
            {note.frontmatter.protected
              ? t("notes.protected.unprotect")
              : t("notes.protected.protect")}
          </Button>
          <Button
            size="sm"
            variant="outline"
            disabled={p11Busy}
            onClick={() =>
              void runP11(() =>
                setLifecycle(
                  apiBase,
                  note.id,
                  note.frontmatter.lifecycle === "cold" ? "active" : "cold",
                  {
                    expectedContentHash: note.content_hash,
                    // Esfriar nota protegida é decisão explícita do humano —
                    // é exatamente o que este clique significa.
                    force: note.frontmatter.protected,
                  },
                ),
              )
            }
          >
            <Snowflake className="mr-1 h-3.5 w-3.5" aria-hidden />
            {note.frontmatter.lifecycle === "cold"
              ? t("notes.lifecycle.reactivate")
              : t("notes.lifecycle.moveToCold")}
          </Button>
          <span className="text-xs text-muted-foreground">
            {t("notes.protected.description")}
          </span>
        </div>

        {p11Error ? (
          <p className="mt-2 text-xs text-destructive" role="alert">
            {p11Error}
          </p>
        ) : null}

        {note.frontmatter.review && note.frontmatter.review.length > 0 ? (
          <div className="mt-3 space-y-2">
            <h2 className="text-sm font-medium text-muted-foreground">
              {t("notes.review.title")}
            </h2>
            {note.frontmatter.review.map((entry) => (
              <ReviewCard
                key={entry.kind}
                entry={entry}
                busy={p11Busy}
                onResolve={(resolution: ReviewResolution) =>
                  void runP11(() => resolveReview(apiBase, note.id, entry.kind, resolution))
                }
                onProtect={() =>
                  void runP11(() =>
                    setProtected(apiBase, note.id, true, {
                      reason: `review ${entry.kind}`,
                    }),
                  )
                }
              />
            ))}
          </div>
        ) : null}
      </header>

      <section>
        <h2 className="text-sm font-medium text-muted-foreground">
          {t("notes.view.body")}
        </h2>
        <div className="mt-2 rounded-md border border-border bg-card p-4">
          <NotePreview body={note.body} />
        </div>
      </section>

      <section>
        <h2 className="text-sm font-medium text-muted-foreground">
          {t("notes.view.frontmatter")}
        </h2>
        <pre className="mt-2 overflow-x-auto rounded-md border border-border bg-muted/30 p-3 text-xs">
          {JSON.stringify(note.frontmatter, null, 2)}
        </pre>
      </section>

      <section>
        <h2 className="text-sm font-medium text-muted-foreground">
          {t("notes.view.history")}
        </h2>
        <dl className="mt-2 grid grid-cols-2 gap-1 text-xs text-muted-foreground">
          <dt>content_hash</dt>
          <dd className="font-mono">{shortHash(note.content_hash)}</dd>
          <dt>body_hash</dt>
          <dd className="font-mono">{shortHash(note.body_hash)}</dd>
        </dl>
        {history === null ? (
          <p className="mt-2 text-xs text-muted-foreground">{t("common.loading")}</p>
        ) : history.length === 0 ? (
          <p className="mt-2 text-xs text-muted-foreground">{t("notes.view.noHistory")}</p>
        ) : (
          <ul className="mt-2 flex flex-col gap-1.5">
            {history.map((commit) => (
              <li
                key={commit.sha}
                className="rounded-md border border-border bg-card p-2 text-xs"
              >
                <div className="flex items-center justify-between gap-2 text-muted-foreground">
                  <span className="font-mono">{shortHash(commit.sha)}</span>
                  <span>{formatTimestamp(commit.timestamp)}</span>
                </div>
                <p className="mt-1">{commit.message}</p>
                <p className="mt-0.5 text-muted-foreground">{commit.author}</p>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2 className="text-sm font-medium text-muted-foreground">
          {t("notes.view.backlinks")}
        </h2>
        {note.backlinks.length === 0 ? (
          <p className="mt-2 text-xs text-muted-foreground">{t("notes.view.noBacklinks")}</p>
        ) : (
          <div className="mt-2 flex flex-wrap gap-2">
            {note.backlinks.map((id) => (
              <Link
                key={id}
                to={{ kind: "note", id }}
                className="inline-flex items-center gap-1 rounded-md border border-border bg-card px-2 py-1 font-mono text-xs hover:bg-accent/50"
              >
                {id}
              </Link>
            ))}
          </div>
        )}
      </section>

      <AlertDialog open={archiveOpen} onOpenChange={(open) => !open && setArchiveOpen(false)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {t("notes.archive.confirm.title", { id: note.id })}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {t("notes.archive.confirm.body")}
            </AlertDialogDescription>
          </AlertDialogHeader>
          {archiveError ? (
            <p className="text-xs text-destructive">{archiveError}</p>
          ) : null}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={archiveBusy}>
              {t("notes.actions.cancel")}
            </AlertDialogCancel>
            <AlertDialogAction onClick={confirmArchive} disabled={archiveBusy}>
              {t("notes.actions.archive")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}