/**
 * ``BundleSelector`` — toggle CM ↔ AK no header (Fase 1 / B1, D52).
 *
 * Estado vive em ``KgClientProvider`` (decisão DC-S2 = "controle no
 * header"). Default ``"cm"`` preserva comportamento atual.
 *
 * Decisão DC-S6: "Extracted" na sidebar é SEMPRE visível, independente
 * do bundle ativo. O seletor afeta listas/search/home, não a presença
 * do item "Extracted" na sidebar.
 */

import { useTranslation } from "react-i18next";
import { Layers, BookOpen } from "lucide-react";
import { useKgClient, type Bundle } from "@/providers/KgClientProvider";
import { useHealth } from "@/hooks/useHealth";
import { cn } from "@/lib/utils";

const OPTIONS: Array<{ value: Bundle; labelKey: string; icon: typeof Layers }> = [
  { value: "cm", labelKey: "bundle.cm", icon: BookOpen },
  { value: "ak", labelKey: "bundle.ak", icon: Layers },
];

export function BundleSelector({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { bundle, setBundle } = useKgClient();
  const { status } = useHealth();

  // M7 — trocar para AK com o adapter down levava a uma UI inteira de
  // EmptyState sem nenhuma pista da causa. Só desabilitamos em
  // ``"error"``: em ``"loading"`` ainda não sabemos nada, e desabilitar
  // aí faria o botão piscar de inativo para ativo em toda sessão.
  // O bundle ATIVO nunca é desabilitado — senão o humano ficaria preso
  // em AK sem conseguir voltar para CM se AK caísse depois da troca.
  const disabledFor = (value: Bundle): boolean =>
    value === "ak" && status.acquire === "error" && bundle !== "ak";

  return (
    <div
      className={cn("inline-flex items-center gap-1 rounded-md border border-border bg-background p-0.5", className)}
      role="radiogroup"
      aria-label={t("bundle.label")}
    >
      {OPTIONS.map(({ value, labelKey, icon: Icon }) => {
        const active = bundle === value;
        const disabled = disabledFor(value);
        return (
          <button
            key={value}
            type="button"
            role="radio"
            aria-checked={active}
            aria-disabled={disabled}
            disabled={disabled}
            title={disabled ? t("bundle.akDisabledHint") : undefined}
            onClick={() => setBundle(value)}
            className={cn(
              "inline-flex items-center gap-1.5 rounded px-2 py-1 text-xs font-medium transition-colors",
              active
                ? "bg-sidebar-accent text-sidebar-accent-foreground"
                : "text-muted-foreground hover:bg-sidebar-accent/50 hover:text-foreground",
              disabled && "cursor-not-allowed opacity-50 hover:bg-transparent hover:text-muted-foreground",
            )}
          >
            <Icon className="h-3.5 w-3.5" />
            {t(labelKey)}
          </button>
        );
      })}
    </div>
  );
}