/**
 * ``SourceView`` — visualização de uma Source com navegação de chunks.
 */

import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { ArrowLeft, ChevronLeft, ChevronRight, Hash } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/kg/Badge";
import { NotePreview } from "@/components/kg/NotePreview";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { useSource } from "@/hooks/useSource";
import { Link } from "@/lib/Link";
import type { ChunkResponse } from "@/lib/types";
import { cn } from "@/lib/utils";

export function SourceView({ sourceId, className }: { sourceId: string; className?: string }) {
  const { t } = useTranslation();
  const { source, loading, error, readChunk, chunkError } = useSource(sourceId);
  const [chunk, setChunk] = useState<ChunkResponse | null>(null);
  const [chunkIndex, setChunkIndex] = useState(0);
  // Bug SPA-5 (revisão): contador de geração protege contra cliques
  // rápidos em prev/next — se o usuário clica chunk 3, depois chunk 2
  // rapidamente, a resposta do chunk 2 chega primeiro e a do chunk
  // 3 DEPOIS: sem o guard, o chunk mostrado seria o 3 enquanto o
  // rótulo diria "chunk 2" (estado dessincronizado). O contador de
  // geração garante que só o resultado da última ``goTo`` aplica.
  const chunkRequestIdRef = useRef(0);

  // ``readChunk`` muda de identidade quando ``sourceId`` muda (useCallback
  // com ``sourceId`` nas deps, ver useSource.ts). Reseta ``chunkIndex``
  // aqui junto — sem isso, navegar de uma Source pro meio de outra (via
  // Link/click, sem remount do componente) deixava o índice de paginação
  // travado no valor da Source anterior enquanto o conteúdo mostrado já
  // era o chunk 0 da nova, dessincronizando o rótulo "chunk N de M" e os
  // botões prev/next.
  useEffect(() => {
    const requestId = ++chunkRequestIdRef.current;
    setChunkIndex(0);
    void readChunk(0).then((c) => {
      if (chunkRequestIdRef.current !== requestId) return;
      if (c) setChunk(c);
    });
  }, [readChunk]);

  const total = (source?.frontmatter.chunks_total as number | undefined) ?? 0;
  // Bug fix (revisão 2026-07-31): a barra de progresso do B11 deve
  // medir progresso de ATOMIZAÇÃO (quantos chunks o agente já
  // converteu em ExtractedNote), não a posição de leitura do humano
  // no navegador de chunks — eram coisas diferentes usando o mesmo
  // elemento visual. ``chunkIndex`` é só "qual chunk estou vendo agora".
  const chunksAtomized = (source?.frontmatter.chunks_atomized as number[] | undefined) ?? [];
  const atomizedCount = chunksAtomized.length;

  if (loading) return <SurfaceLoadingFallback className={className} />;
  if (error) return <EmptyStateI18n messageKey="errors.network" className={className} />;
  if (!source) return <EmptyStateI18n messageKey="errors.notFound" className={className} />;

  const goTo = async (idx: number) => {
    if (idx < 0 || idx >= total) return;
    const requestId = ++chunkRequestIdRef.current;
    setChunkIndex(idx);
    const c = await readChunk(idx);
    if (chunkRequestIdRef.current !== requestId) return;
    setChunk(c);
  };

  return (
    <div className={cn("flex h-full flex-col gap-4 overflow-y-auto p-6", className)}>
      <div className="flex items-center justify-between">
        <Link
          to={{ kind: "sources" }}
          className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"
        >
          <ArrowLeft className="h-3.5 w-3.5" />
          {t("notes.actions.back")}
        </Link>
      </div>

      <header>
        <h1 className="text-2xl font-semibold">
          {(source.frontmatter.title as string | undefined) ?? sourceId}
        </h1>
        <div className="mt-2 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          {source.frontmatter.source_kind && (
            <Badge variant="outline">{String(source.frontmatter.source_kind)}</Badge>
          )}
          {source.frontmatter.media_type && (
            <span className="font-mono">{String(source.frontmatter.media_type)}</span>
          )}
          <span className="flex items-center gap-1">
            <Hash className="h-3 w-3" />
            <span className="font-mono">{sourceId}</span>
          </span>
        </div>
      </header>

      <section>
        <h2 className="text-sm font-medium text-muted-foreground">
          {t("sources.view.chunks")}
        </h2>
        <div className="mt-2 flex items-center justify-between">
          <span className="text-xs text-muted-foreground">
            {t("sources.view.chunkNumber", { n: chunkIndex + 1, total })}
          </span>
          <div className="flex gap-2">
            <Button
              variant="outline"
              size="sm"
              disabled={chunkIndex === 0}
              onClick={() => goTo(chunkIndex - 1)}
            >
              <ChevronLeft className="h-3.5 w-3.5" />
              {t("sources.view.prev")}
            </Button>
            <Button
              variant="outline"
              size="sm"
              disabled={chunkIndex >= total - 1}
              onClick={() => goTo(chunkIndex + 1)}
            >
              {t("sources.view.next")}
              <ChevronRight className="h-3.5 w-3.5" />
            </Button>
          </div>
        </div>

        {/* B11 — progress bar showing atomization progress (Fase 4).
            Mede ``chunks_atomized.length / chunks_total`` — quanto do
            Source já foi processado pelo agente, não onde o humano
            está navegando (isso já é mostrado no rótulo "Chunk N of M"
            acima). */}
        {total > 0 && (
          <div className="mt-2 h-1 w-full overflow-hidden rounded-full bg-muted">
            <div
              className="h-full bg-primary transition-[width] duration-200"
              style={{ width: `${Math.min(100, (atomizedCount / total) * 100)}%` }}
              aria-label={`${t("sources.chunksAtomized")}: ${atomizedCount}/${total}`}
            />
          </div>
        )}

        <div className="mt-2 rounded-md border border-border bg-card p-4">
          {chunk ? (
            <NotePreview body={chunk.text} />
          ) : chunkError ? (
            /* M3 — falha real de leitura (500, timeout, adapter down).
               Antes ficava preso em "Loading…" para sempre. */
            <p className="text-sm text-destructive">
              {t("errors.network")} · {chunkError}
            </p>
          ) : (
            <p className="text-sm text-muted-foreground">
              {t("common.loading")}
            </p>
          )}
        </div>
      </section>
    </div>
  );
}
